svg.script:
(function() {
  const svg = document.getElementById('rapoo-vt9-svg');
  const state = {
    activeTab: 0,
    dpi: 1600,
    pollRate: 1000,
    lod: 3,
    sleepMin: 30,
    debounceMode: 'press',
    debounceMs: 8,
    switches: {
      autoStart: false,
      lowBatt: true,
      motionSync: true,
      dpi: [true, true, true, true, true, false, false]
    }
  };

  const pages = [
    document.getElementById('page-0'),
    document.getElementById('page-1'),
    document.getElementById('page-2'),
    document.getElementById('page-3')
  ];

  function setSwitchVisual(switchElem, isOn) {
    if (!switchElem) return;
    const track = switchElem.querySelector('.switch-track');
    const knob = switchElem.querySelector('.switch-knob');
    if (track) track.setAttribute('fill', isOn ? '#304ffe' : '#cbd5e1');
    if (knob) {
      knob.style.transform = isOn ? 'translateX(22px)' : 'translateX(0px)';
    }
  }

  function bindToggle(switchId, initialVal, onToggle) {
    const elem = document.getElementById(switchId);
    if (!elem) return;
    let active = initialVal;
    setSwitchVisual(elem, active);

    elem.addEventListener('click', (e) => {
      e.stopPropagation();
      active = !active;
      setSwitchVisual(elem, active);
      if (onToggle) onToggle(active);
    });
  }

  bindToggle('sw-auto-start', state.switches.autoStart, (on) => {
    state.switches.autoStart = on;
    const txt = document.getElementById('txt-auto-start-status');
    if (txt) {
      txt.textContent = on ? '已开启' : '未启用';
      txt.style.fill = on ? '#111827' : '#8a94a6';
    }
  });

  bindToggle('sw-low-batt', state.switches.lowBatt, (on) => {
    state.switches.lowBatt = on;
    const txt = document.getElementById('txt-low-batt-status');
    if (txt) {
      txt.textContent = on ? '已开启 • 阈值 20%' : '未启用';
      txt.style.fill = on ? '#111827' : '#8a94a6';
    }
  });

  bindToggle('sw-motion-sync', state.switches.motionSync, (on) => {
    state.switches.motionSync = on;
    const sumM = document.getElementById('sum-motion');
    if (sumM) sumM.textContent = on ? '开' : '关';
  });

  state.switches.dpi.forEach((val, idx) => {
    bindToggle('sw-dpi-' + idx, val, (on) => {
      state.switches.dpi[idx] = on;
      const txtVal = document.getElementById('txt-val-' + idx);
      if (txtVal && !on) {
        txtVal.textContent = '未启用';
        txtVal.style.fill = '#94a3b8';
      } else if (txtVal && on) {
        const defaultMap = [800, 1200, 1600, 2000, 3200, 6400, 20000];
        txtVal.textContent = defaultMap[idx];
        txtVal.style.fill = '#111827';
      }
    });
  });

  function bindPillGroup(pillConfigs, onSelect) {
    pillConfigs.forEach(cfg => {
      const btn = document.getElementById(cfg.id);
      if (!btn) return;

      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        pillConfigs.forEach(item => {
          const el = document.getElementById(item.id);
          if (!el) return;
          const rect = el.querySelector('.pill-rect');
          const txt = el.querySelector('.pill-text');
          const isSelected = (item.id === cfg.id);

          if (rect) rect.setAttribute('fill', isSelected ? '#304ffe' : '#edf2f7');
          if (txt) {
            txt.style.fill = isSelected ? '#ffffff' : '#475569';
            txt.style.fontWeight = isSelected ? '700' : '600';
          }
        });

        if (onSelect) onSelect(cfg.val);
      });
    });
  }

  bindPillGroup([
    { id: 'dpi-pill-800', val: 800 },
    { id: 'dpi-pill-1200', val: 1200 },
    { id: 'dpi-pill-1600', val: 1600 },
    { id: 'dpi-pill-2000', val: 2000 },
    { id: 'dpi-pill-3200', val: 3200 },
    { id: 'dpi-pill-6400', val: 6400 },
    { id: 'dpi-pill-20000', val: 20000 }
  ], (dpiVal) => {
    state.dpi = dpiVal;
    const hero = document.getElementById('dpi-hero-val');
    if (hero) hero.textContent = dpiVal;
    const sumD = document.getElementById('sum-dpi');
    if (sumD) {
      const list = [800, 1200, 1600, 2000, 3200, 6400, 20000];
      const rank = list.indexOf(dpiVal) + 1;
      sumD.textContent = (rank > 0 ? ('第 ' + rank + ' 档') : '当前') + ' • ' + dpiVal + ' DPI';
    }
  });

  bindPillGroup([
    { id: 'poll-pill-125', val: 125 },
    { id: 'poll-pill-250', val: 250 },
    { id: 'poll-pill-500', val: 500 },
    { id: 'poll-pill-1000', val: 1000 }
  ], (poll) => {
    state.pollRate = poll;
    const sumP = document.getElementById('sum-poll');
    if (sumP) sumP.textContent = poll + ' Hz';
  });

  bindPillGroup([
    { id: 'lod-pill-1', val: 1 },
    { id: 'lod-pill-2', val: 2 },
    { id: 'lod-pill-3', val: 3 }
  ], (lod) => {
    state.lod = lod;
    const sumL = document.getElementById('sum-lod');
    if (sumL) sumL.textContent = lod + ' mm';
  });

  bindPillGroup([
    { id: 'sleep-pill-5', val: 5 },
    { id: 'sleep-pill-10', val: 10 },
    { id: 'sleep-pill-30', val: 30 },
    { id: 'sleep-pill-60', val: 60 },
    { id: 'sleep-pill-120', val: 120 }
  ], (mins) => {
    state.sleepMin = mins;
    const txt = document.getElementById('txt-sleep-val');
    if (txt) txt.textContent = mins + ' 分钟';
    const sumS = document.getElementById('sum-sleep');
    if (sumS) sumS.textContent = mins + ' 分钟';

    const line = document.getElementById('sleep-fill-line');
    const thumb = document.getElementById('sleep-thumb');
    const xPos = (mins / 120) * 680;
    if (line) line.setAttribute('x2', xPos);
    if (thumb) thumb.setAttribute('cx', xPos);
  });

  function updateDebounceSummary() {
    const sumDeb = document.getElementById('sum-debounce');
    if (sumDeb) {
      const modeCn = state.debounceMode === 'press' ? '按下' : '抬起';
      sumDeb.textContent = state.debounceMs + ' ms · ' + modeCn;
    }
  }

  bindPillGroup([
    { id: 'pill-mode-press', val: 'press' },
    { id: 'pill-mode-lift', val: 'lift' }
  ], (mode) => {
    state.debounceMode = mode;
    updateDebounceSummary();
  });

  bindPillGroup([
    { id: 'db-pill-1', val: 1 },
    { id: 'db-pill-2', val: 2 },
    { id: 'db-pill-4', val: 4 },
    { id: 'db-pill-8', val: 8 },
    { id: 'db-pill-16', val: 16 },
    { id: 'db-pill-24', val: 24 },
    { id: 'db-pill-32', val: 32 }
  ], (ms) => {
    state.debounceMs = ms;
    updateDebounceSummary();
  });

  const tabOffsets = [0, 104, 208, 312];
  const slider = document.getElementById('glass-slider');
  const clipRect = document.getElementById('clip-rect');
  const baseMaskRect = document.getElementById('base-mask-rect');

  function playCardSlideIn(pageEl) {
    if (!pageEl) return;
    pageEl.classList.remove('play-in');

    const cards = Array.from(pageEl.querySelectorAll(':scope > .dash-card'));
    const items = cards.map(el => {
      const m = /translate\(\s*(-?[\d.]+)[ ,]+(-?[\d.]+)\s*\)/.exec(el.getAttribute('transform') || '');
      return { el, x: m ? parseFloat(m[1]) : 0, y: m ? parseFloat(m[2]) : 0 };
    });

    items.sort((a, b) =>
      (a.y - b.y) || (a.x - b.x)
    );

    items.forEach((item, i) => {
      item.el.style.animationDelay = (i * 55) + 'ms';
    });

    void pageEl.getBoundingClientRect();
    pageEl.classList.add('play-in');
  }

  function snapDockToTab(tabIdx, wall = false) {
    stopDockFrame();
    const from = { y: dockMotion.y, sy: dockMotion.sy };
    const dest = tabOffsets[tabIdx];
    const duration = dockSnapDuration(dest - from.y, wall);
    slider.dataset.snapKind = wall ? 'wall' : 'smooth';
    slider.dataset.snapDuration = String(reducedDockMotion.matches ? 0 : duration);
    if (reducedDockMotion.matches) { writeDockPose(dest, 1); return; }
    const started = performance.now();
    function settle(now) {
      const t = Math.min(1, (now - started) / duration);
      const e = dockEase(t, wall);
      writeDockPose(from.y + (dest - from.y) * e, from.sy + (1 - from.sy) * e);
      if (t < 1) dockFrame = requestAnimationFrame(settle);
      else { dockFrame = null; writeDockPose(dest, 1); }
    }
    dockFrame = requestAnimationFrame(settle);
  }

  // The sole page-switch entry for both clicks and drag releases.
  function switchTab(newTabIdx, wallRelease = false) {
    if (!Number.isInteger(newTabIdx) || !pages[newTabIdx]) return;
    snapDockToTab(newTabIdx, wallRelease);
    if (newTabIdx === state.activeTab) return;
    pages.forEach(p => {
      p.classList.remove('play-in');
      p.querySelectorAll(':scope > .dash-card').forEach(card => {
        card.style.animationDelay = '';
      });
      p.style.transition = 'none';
      p.style.display = 'none';
      p.style.opacity = '0';
    });
    const pageEl = pages[newTabIdx];
    pageEl.style.display = 'inline';
    // Leave the parent at its default opacity; only individual cards fade in.
    pageEl.style.removeProperty('opacity');
    state.activeTab = newTabIdx;
    playCardSlideIn(pageEl);
  }

  let lastDockDragEndTime = -Infinity;
  [0, 1, 2, 3].forEach(idx => {
    const hit = document.getElementById('tab-hit-' + idx);
    if (hit) {
      hit.addEventListener('click', (e) => {
        e.stopPropagation();
        if (performance.now() - lastDockDragEndTime < 120) return;
        switchTab(idx);
      });
    }
  });

  const dockEl = document.getElementById('left-dock');
  const dockMaximum = Math.max(312, Number(dockEl.querySelector('rect').getAttribute('height')) - 94);
  const reducedDockMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let dockPointerDown = false, dockDragging = false;
  let dockStartPointerY = 0, dockStartOffset = 0, dockPointerId = null, pendingTab = 0;
  let dockFrame = null, dockFrameTime = 0;
  const dockMotion = { y: 0, raw: 0, v: 0, sy: 1, sx: 1 };

  // BEGIN DOCK PHYSICS: pure functions, shared numerical model with WPF.
  function dockRubberClamp(raw, maximum) {
    if (raw < 0) return -6 * (1 - Math.exp(raw / 40));
    if (raw > maximum) return maximum + 6 * (1 - Math.exp(-(raw - maximum) / 40));
    return raw;
  }
  function dockPressure(m, maximum) {
    if (m.raw < 0 && m.y < 4) return Math.min(1, -m.raw / 60);
    if (m.raw > maximum && m.y > maximum - 4) return Math.min(1, (m.raw - maximum) / 60);
    return 0;
  }
  function dockStep(m, seconds, maximum) {
    const dt = Math.max(0.001, Math.min(0.05, seconds));
    const before = m.y;
    m.y += (dockRubberClamp(m.raw, maximum) - m.y) * (1 - Math.exp(-dt / 0.075));
    m.v += ((m.y - before) / dt - m.v) * (1 - Math.exp(-dt / 0.045));
    const pressure = dockPressure(m, maximum);
    const stretch = Math.min(0.18, Math.abs(m.v) / 2400 * 0.18);
    const shape = pressure > 0 ? 1 - 0.07 * pressure : 1 + stretch;
    m.sy += (shape - m.sy) * (1 - Math.exp(-dt / 0.065));
    m.sx = 1 / m.sy;
  }
  function dockSnapDuration(distance, wall) {
    return Math.max(170, Math.min(420, 170 + Math.abs(distance) * 0.55)) + (wall ? 70 : 0);
  }
  function dockEase(t, wall) {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    const bezier = (u, a, b) => 3*(1-u)*(1-u)*u*a + 3*(1-u)*u*u*b + u*u*u;
    let lo = 0, hi = 1;
    for (let i = 0; i < 28; i++) {
      const mid = (lo + hi) / 2;
      if (bezier(mid, 0.2, 0.3) < t) lo = mid; else hi = mid;
    }
    return bezier((lo + hi)/2, wall ? 1.22 : 0.9, 1);
  }
  // END DOCK PHYSICS

  function nearestDockTab(y) { return Math.max(0, Math.min(3, Math.floor(y / 104 + 0.5))); }
  function stopDockFrame() {
    if (dockFrame !== null) cancelAnimationFrame(dockFrame);
    dockFrame = null;
  }
  function writeDockPose(y, sy) {
    dockMotion.y = y; dockMotion.sy = sy; dockMotion.sx = 1 / sy;
    const transform = `translateY(${y}px) translate(70px, 123px) scale(${dockMotion.sx}, ${sy}) translate(-70px, -123px)`;
    slider.style.transition = clipRect.style.transition = baseMaskRect.style.transition = 'none';
    slider.style.transform = clipRect.style.transform = baseMaskRect.style.transform = transform;
  }
  function followDock(now) {
    if (!dockPointerDown || !dockDragging) { dockFrame = null; return; }
    dockStep(dockMotion, (now - dockFrameTime) / 1000, dockMaximum);
    dockFrameTime = now;
    writeDockPose(dockMotion.y, dockMotion.sy);
    pendingTab = nearestDockTab(dockMotion.y);
    dockFrame = requestAnimationFrame(followDock);
  }
  function getDockLocalY(e) {
    const pt = svg.createSVGPoint(); pt.x = e.clientX; pt.y = e.clientY;
    return pt.matrixTransform(dockEl.getScreenCTM().inverse()).y;
  }
  dockEl.addEventListener('pointerdown', e => {
    if (e.button !== 0 || !e.isPrimary) return;
    const y = getDockLocalY(e);
    if (y < 76 || y > 582) return;
    stopDockFrame();
    dockPointerDown = true; dockDragging = false;
    dockStartPointerY = y; dockStartOffset = dockMotion.y;
    dockMotion.raw = dockMotion.y; dockMotion.v = 0;
    dockPointerId = e.pointerId; pendingTab = state.activeTab;
  });
  dockEl.addEventListener('pointermove', e => {
    if (!dockPointerDown || e.pointerId !== dockPointerId) return;
    if (e.pointerType === 'mouse' && (e.buttons & 1) === 0) { cancelDockDrag(); return; }
    const delta = getDockLocalY(e) - dockStartPointerY;
    if (!dockDragging && Math.abs(delta) > 4) {
      dockDragging = true;
      try { dockEl.setPointerCapture(dockPointerId); } catch (_) {}
    }
    if (!dockDragging) return;
    dockMotion.raw = dockStartOffset + delta;
    if (reducedDockMotion.matches) {
      writeDockPose(Math.max(0, Math.min(dockMaximum, dockMotion.raw)), 1);
      pendingTab = nearestDockTab(dockMotion.y);
    } else if (dockFrame === null) {
      dockFrameTime = performance.now();
      dockFrame = requestAnimationFrame(followDock);
    }
  });
  function releaseDockPointer() {
    const id = dockPointerId;
    dockPointerDown = false; dockDragging = false; dockPointerId = null;
    stopDockFrame();
    if (id !== null) { try { dockEl.releasePointerCapture(id); } catch (_) {} }
  }
  function finishDockDrag(e) {
    if (!dockPointerDown || e.pointerId !== dockPointerId) return;
    const dragged = dockDragging;
    const wall = dockPressure(dockMotion, dockMaximum) > 0 && dockMotion.sy < 0.995;
    pendingTab = nearestDockTab(dockMotion.y);
    releaseDockPointer();
    if (!dragged) return;
    lastDockDragEndTime = performance.now();
    switchTab(pendingTab, wall);
  }
  function cancelDockDrag() {
    if (!dockPointerDown) return;
    if (dockDragging) lastDockDragEndTime = performance.now();
    const wall = dockPressure(dockMotion, dockMaximum) > 0 && dockMotion.sy < 0.995;
    releaseDockPointer();
    switchTab(state.activeTab, wall);
  }
  dockEl.addEventListener('pointerup', finishDockDrag);
  dockEl.addEventListener('pointercancel', cancelDockDrag);
  dockEl.addEventListener('lostpointercapture', cancelDockDrag);
  window.addEventListener('blur', cancelDockDrag);

  function bindSliderDrag(wrapEl, { minX, maxX, onDrag, onRelease, enabled }) {
    if (!wrapEl) return;
    let dragging = false;

    function toLocalX(e) {
      const pt = wrapEl.ownerSVGElement.createSVGPoint();
      pt.x = e.clientX; pt.y = e.clientY;
      return pt.matrixTransform(wrapEl.getScreenCTM().inverse()).x;
    }
    const clampX = (x) => Math.max(minX, Math.min(maxX, x));

    wrapEl.addEventListener('pointerdown', (e) => {
      if (enabled && !enabled()) return;
      e.stopPropagation();
      dragging = true;
      try { wrapEl.setPointerCapture(e.pointerId); } catch (_) {}
      onDrag(clampX(toLocalX(e)));
    });

    wrapEl.addEventListener('pointermove', (e) => {
      if (!dragging) return;
      onDrag(clampX(toLocalX(e)));
    });

    const finish = (e) => {
      if (!dragging) return;
      dragging = false;
      try { wrapEl.releasePointerCapture(e.pointerId); } catch (_) {}
      if (onRelease) onRelease(clampX(toLocalX(e)));
    };

    wrapEl.addEventListener('pointerup', finish);
    wrapEl.addEventListener('pointercancel', finish);
  }

  // 1. DPI 7 档滑轨接线
  for (let i = 0; i < 7; i++) {
    const wrap = document.getElementById('slider-wrap-' + i);
    const line = document.getElementById('fill-line-' + i);
    const thumb = document.getElementById('thumb-' + i);
    const txtVal = document.getElementById('txt-val-' + i);

    bindSliderDrag(wrap, {
      minX: 0, maxX: 480,
      enabled: () => state.switches.dpi[i],
      onDrag: (x) => {
        const dpi = Math.max(100, Math.min(8000, Math.round(x / 0.06 / 50) * 50));
        const px = dpi * 0.06;
        if (line) line.setAttribute('x2', px);
        if (thumb) thumb.setAttribute('cx', px);
        if (txtVal) txtVal.textContent = dpi;
      }
    });
  }

  // 2. 休眠时间滑轨接线 (松手吸附最近 pill)
  const SLEEP_STEPS = [5, 10, 30, 60, 120];
  const SLEEP_W = 680;
  let sleepDragX = null;

  bindSliderDrag(document.getElementById('sleep-slider-track'), {
    minX: 0, maxX: SLEEP_W,
    onDrag: (x) => {
      sleepDragX = x;
      const mins = Math.round(x / SLEEP_W * 120);
      const l = document.getElementById('sleep-fill-line');
      const t = document.getElementById('sleep-thumb');
      const txt = document.getElementById('txt-sleep-val');
      if (l) l.setAttribute('x2', x);
      if (t) t.setAttribute('cx', x);
      if (txt) txt.textContent = mins + ' 分钟';
    },
    onRelease: () => {
      if (sleepDragX == null) return;
      const approx = sleepDragX / SLEEP_W * 120;
      const nearest = SLEEP_STEPS.reduce((a, b) =>
        Math.abs(b - approx) < Math.abs(a - approx) ? b : a);
      sleepDragX = null;
      const pill = document.getElementById('sleep-pill-' + nearest);
      if (pill) pill.dispatchEvent(new MouseEvent('click', { bubbles: false }));
    }
  });

  // 3. 卡片与整窗背景透明度滑轨接线
  [
    { track: 'card-opacity-track', fill: 'card-opacity-fill', thumb: 'card-opacity-thumb', txt: 'txt-card-opacity' },
    { track: 'win-opacity-track', fill: 'win-opacity-fill', thumb: 'win-opacity-thumb', txt: 'txt-win-opacity' }
  ].forEach(({ track, fill, thumb, txt }) => {
    const line = document.getElementById(fill);
    const dot = document.getElementById(thumb);
    const label = document.getElementById(txt);
    bindSliderDrag(document.getElementById(track), {
      minX: 0, maxX: 760,
      onDrag: (x) => {
        const pct = Math.round(x / 760 * 100);
        const px = pct / 100 * 760;
        if (line) line.setAttribute('x2', px);
        if (dot) dot.setAttribute('cx', px);
        if (label) label.textContent = pct + '%';
      }
    });
  });

  // 首屏加载：page-0 卡片依次滑入
  requestAnimationFrame(() => {
    playCardSlideIn(pages[0]);
  });
})();
